import React from 'react';
import { Card, CardContent, Box, Typography, Avatar, LinearProgress } from '@mui/material';
import { TrendingUp as TrendingUpIcon, TrendingDown as TrendingDownIcon } from '@mui/icons-material';

const StatCard = ({ title, value, icon, trend, trendValue, color = 'primary', progress }) => {
  const isPositive = trend === 'up';

  const getGradient = (colorName) => {
    const gradients = {
      primary: 'linear-gradient(135deg, #FFB300 0%, #FF8F00 100%)',
      success: 'linear-gradient(135deg, #2E7D32 0%, #1B5E20 100%)',
      info: 'linear-gradient(135deg, #0288D1 0%, #01579B 100%)',
      warning: 'linear-gradient(135deg, #ED6C02 0%, #E65100 100%)',
      error: 'linear-gradient(135deg, #D32F2F 0%, #B71C1C 100%)',
    };
    return gradients[colorName] || gradients.primary;
  };

  const getLightColor = (colorName) => {
    const colors = {
      primary: 'rgba(255, 179, 0, 0.1)',
      success: 'rgba(46, 125, 50, 0.1)',
      info: 'rgba(2, 136, 209, 0.1)',
      warning: 'rgba(237, 108, 2, 0.1)',
      error: 'rgba(211, 47, 47, 0.1)',
    };
    return colors[colorName] || colors.primary;
  };

  return (
      <Card
      sx={{
        height: '100%',
        background: 'linear-gradient(135deg, #FFFFFF 0%, #FFFCF5 100%)',
        border: '1px solid rgba(255, 179, 0, 0.1)',
        borderRadius: 4,
        transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
        position: 'relative',
        overflow: 'hidden',
        '&::before': {
          content: '""',
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: 4,
          background: getGradient(color),
        },
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: '0 12px 40px rgba(255, 179, 0, 0.12)',
        },
      }}
    >
      <CardContent sx={{ p: 3, position: 'relative', zIndex: 1 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
          <Avatar
            sx={{
              width: 56,
              height: 56,
              background: getGradient(color),
              color: 'white',
              boxShadow: `0 8px 16px ${getLightColor(color)}`,
            }}
          >
            {icon}
          </Avatar>
          {trend && (
            <Box 
              sx={{ 
                display: 'flex', 
                alignItems: 'center',
                bgcolor: isPositive ? 'rgba(17, 153, 142, 0.1)' : 'rgba(244, 67, 54, 0.1)',
                px: 1.5,
                py: 0.5,
                borderRadius: 2,
              }}
            >
              {isPositive ? (
                <TrendingUpIcon sx={{ color: '#11998e', fontSize: 18, mr: 0.5 }} />
              ) : (
                <TrendingDownIcon sx={{ color: '#f44336', fontSize: 18, mr: 0.5 }} />
              )}
              <Typography
                variant="caption"
                sx={{ 
                  color: isPositive ? '#11998e' : '#f44336', 
                  fontWeight: 700 
                }}
              >
                {trendValue}
              </Typography>
            </Box>
          )}
        </Box>

        <Typography 
          variant="h3" 
          sx={{ 
            fontWeight: 800, 
            mb: 0.5, 
            color: 'text.primary',
            background: getGradient(color),
            backgroundClip: 'text',
            textFillColor: 'transparent',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          {value}
        </Typography>
        <Typography variant="body2" sx={{ color: 'text.secondary', fontWeight: 500 }}>
          {title}
        </Typography>

        {progress !== undefined && (
          <Box sx={{ mt: 2 }}>
            <LinearProgress
              variant="determinate"
              value={progress}
              sx={{
                height: 6,
                borderRadius: 3,
                bgcolor: getLightColor(color),
                '& .MuiLinearProgress-bar': {
                  background: getGradient(color),
                  borderRadius: 3,
                },
              }}
            />
            <Typography variant="caption" sx={{ color: 'text.secondary', mt: 0.5, display: 'block' }}>
              {progress}% of target
            </Typography>
          </Box>
        )}
      </CardContent>
    </Card>
  );
};

export default StatCard;
