// DriverLocationSimulator.jsx
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { io } from 'socket.io-client';

const DriverLocationSimulator = ({ driverId, initialLat = 22.72348238088641, initialLng = 75.89196179870184 }) => {
  const [isSimulating, setIsSimulating] = useState(false);
  const [currentLocation, setCurrentLocation] = useState({ 
    lat: initialLat, 
    lng: initialLng 
  });
  const [socket, setSocket] = useState(null);
  const [logs, setLogs] = useState([]);
  
  // Use ref to always have access to the latest location in intervals
  const locationRef = useRef(currentLocation);
  const intervalRef = useRef(null);
  const socketRef = useRef(null);

  // Update ref when location changes
  useEffect(() => {
    locationRef.current = currentLocation;
  }, [currentLocation]);

  // Add log entry
  const addLog = (message) => {
    setLogs(prev => [`${new Date().toLocaleTimeString()}: ${message}`, ...prev].slice(0, 10));
  };

  useEffect(() => {
    // Connect to socket
    const newSocket = io('https://godelivo.com', {
      transports: ['websocket'],
      reconnection: true
    });
    
    socketRef.current = newSocket;
    setSocket(newSocket);

    newSocket.on('connect', () => {
      console.log('✅ Simulator socket connected');
      addLog('Socket connected');
    });

    newSocket.on('connect_error', (error) => {
      console.error('Socket connection error:', error);
      addLog(`Socket error: ${error.message}`);
    });

    return () => {
      if (newSocket) newSocket.disconnect();
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  const startSimulation = () => {
    if (isSimulating) return;
    
    setIsSimulating(true);
    addLog('Simulation started');
    
    // Clear any existing interval
    if (intervalRef.current) clearInterval(intervalRef.current);
    
    // Simulate movement every 3 seconds
    intervalRef.current = setInterval(async () => {
      // Use the ref to get the latest location
      const currentLoc = locationRef.current;
      
      // Generate random movement (small changes)
      const newLat = currentLoc.lat + (Math.random() - 0.5) * 0.002;
      const newLng = currentLoc.lng + (Math.random() - 0.5) * 0.002;
      
      console.log('📍 Moving from:', currentLoc, 'to:', { lat: newLat, lng: newLng });
      
      // Update state with new location
      setCurrentLocation({ lat: newLat, lng: newLng });
      
      try {
        // Send to backend
        const response = await axios.post('https://godelivo.com/api/rides/update-location', {
          latitude: newLat,
          longitude: newLng
        }, {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpZCI6IjY5YjkwNzgzNWExZGJhMWRmMTk1ZmMzYSIsInBob25lIjoiNzQ3NzI0NjQ3NyIsInR5cGUiOiJkcml2ZXJfYXV0aCIsInJvbGUiOiJkcml2ZXIiLCJpYXQiOjE3NzM3MzM3NjMsImV4cCI6MTc3NjMyNTc2M30.I7gj-Z5fbg6qyD8hPyNT-Wx7FhKa1BmNGOVNi3AA0B8`
          }
        });

        if (response.data.success) {
          addLog(`Location updated: ${newLat.toFixed(6)}, ${newLng.toFixed(6)}`);
        }

        // Also emit directly through socket for real-time
        if (socketRef.current && socketRef.current.connected) {
          socketRef.current.emit('driver:location_update', {
            driverId,
            lat: newLat,
            lng: newLng,
            vehicleType: 'car',
            name: 'Simulated Driver',
            vehicleNumber: 'DL 1234',
            rating: 4.5,
            isOnline: true,
            isAvailable: true,
            timestamp: new Date().toISOString()
          });
          
          // Also emit the event that your NearbyDrivers component is listening for
          socketRef.current.emit('driver:location_updated', {
            driverId,
            lat: newLat,
            lng: newLng,
            vehicleType: 'car',
            name: 'Simulated Driver',
            vehicleNumber: 'DL 1234',
            rating: 4.5,
            isOnline: true,
            isAvailable: true,
            timestamp: new Date().toISOString()
          });
          
          addLog('Socket update emitted');
        }

        console.log('📍 Location updated successfully:', { newLat, newLng });
      } catch (error) {
        console.error('Failed to update location:', error);
        addLog(`Error: ${error.message}`);
      }
    }, 3000);
  };

  const stopSimulation = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setIsSimulating(false);
    addLog('Simulation stopped');
  };

  const resetLocation = () => {
    setCurrentLocation({ lat: initialLat, lng: initialLng });
    addLog(`Reset to initial location: ${initialLat}, ${initialLng}`);
  };

  return (
    <div style={{ 
      padding: '20px', 
      background: '#f0f0f0', 
      borderRadius: '8px',
      maxWidth: '500px',
      margin: '20px'
    }}>
      <h3 style={{ margin: '0 0 15px 0' }}>🚗 Driver Location Simulator</h3>
      
      <div style={{ marginBottom: '15px' }}>
        <div style={{ 
          background: '#fff', 
          padding: '10px', 
          borderRadius: '4px',
          marginBottom: '10px'
        }}>
          <strong>Current Location:</strong>
          <p style={{ margin: '5px 0', fontFamily: 'monospace' }}>
            Lat: {currentLocation.lat?.toFixed(6) || 'N/A'}<br />
            Lng: {currentLocation.lng?.toFixed(6) || 'N/A'}
          </p>
        </div>
        
        <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
          <button 
            onClick={startSimulation}
            disabled={isSimulating}
            style={{
              padding: '10px 20px',
              background: isSimulating ? '#ccc' : '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: isSimulating ? 'not-allowed' : 'pointer',
              flex: 1
            }}
          >
            {isSimulating ? '🔄 Simulating...' : '▶️ Start Simulation'}
          </button>
          
          {isSimulating && (
            <button 
              onClick={stopSimulation}
              style={{
                padding: '10px 20px',
                background: '#ff4444',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                flex: 1
              }}
            >
              ⏸️ Stop
            </button>
          )}
          
          <button 
            onClick={resetLocation}
            style={{
              padding: '10px 20px',
              background: '#2196F3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            🔄 Reset
          </button>
        </div>
      </div>

      {/* Logs */}
      <div style={{
        background: '#1e1e1e',
        color: '#00ff00',
        padding: '10px',
        borderRadius: '4px',
        fontFamily: 'monospace',
        fontSize: '12px',
        maxHeight: '150px',
        overflowY: 'auto'
      }}>
        {logs.map((log, index) => (
          <div key={index} style={{ margin: '2px 0' }}>{log}</div>
        ))}
        {logs.length === 0 && <div style={{ color: '#666' }}>No logs yet...</div>}
      </div>
    </div>
  );
};

export default DriverLocationSimulator;