import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  TextField,
  Button,
  Typography,
  Alert,
  CircularProgress,
  InputAdornment,
  Container,
  Paper,
} from '@mui/material';
import { Phone, Verified as VerifiedIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { useCustomerAuth } from '../contexts/CustomerAuthContext';
import toast from 'react-hot-toast';

const MobileLogin = () => {
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [countdown, setCountdown] = useState(0);
  
  const navigate = useNavigate();
  const { login, isAuthenticated } = useCustomerAuth();

  useEffect(() => {
    if (isAuthenticated) {
      navigate('/mobile/support');
    }
  }, [isAuthenticated, navigate]);

  useEffect(() => {
    let timer;
    if (countdown > 0) {
      timer = setTimeout(() => setCountdown(countdown - 1), 1000);
    }
    return () => clearTimeout(timer);
  }, [countdown]);

  const handleSendOTP = async () => {
    if (phone.length !== 10) {
      toast.error('Please enter a valid 10-digit phone number');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch('https://godelivo.com/api/auth/mobile/send-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mobile: phone })
      });

      const data = await response.json();

      if (data.success) {
        setOtpSent(true);
        setCountdown(60);
        toast.success('OTP sent successfully!');
        console.log('OTP for testing:', data.data.otp); // For testing
      } else {
        toast.error(data.message || 'Failed to send OTP');
      }
    } catch (error) {
      toast.error('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOTP = async () => {
    if (otp.length !== 6) {
      toast.error('Please enter a valid 6-digit OTP');
      return;
    }

    setLoading(true);
    try {
      const result = await login(phone, otp);
      
      if (result.success) {
        toast.success('Login successful!');
        navigate('/mobile/support');
      } else {
        toast.error(result.error || 'Invalid OTP');
      }
    } catch (error) {
      toast.error('Verification failed');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOTP = async () => {
    if (countdown > 0) return;

    setLoading(true);
    try {
      const response = await fetch('https://godelivo.com/api/auth/mobile/resend-otp', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mobile: phone })
      });

      const data = await response.json();

      if (data.success) {
        setCountdown(60);
        toast.success('OTP resent successfully!');
      } else {
        toast.error(data.message || 'Failed to resend OTP');
      }
    } catch (error) {
      toast.error('Network error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container maxWidth="sm">
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          py: 4
        }}
      >
        <Paper elevation={3} sx={{ width: '100%', borderRadius: 2, overflow: 'hidden' }}>
          <Box sx={{ bgcolor: '#FFB300', p: 3, textAlign: 'center' }}>
            <Typography variant="h5" sx={{ fontWeight: 700, color: '#000' }}>
              Customer Support
            </Typography>
            <Typography variant="body2" sx={{ color: 'rgba(0,0,0,0.7)' }}>
              Login with your mobile number
            </Typography>
          </Box>

          <CardContent sx={{ p: 4 }}>
            {!otpSent ? (
              // Phone Input Screen
              <Box>
                <TextField
                  fullWidth
                  label="Mobile Number"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/\D/g, ''))}
                  disabled={loading}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <Typography sx={{ color: '#FFB300', fontWeight: 600 }}>+91</Typography>
                      </InputAdornment>
                    ),
                  }}
                  inputProps={{ maxLength: 10 }}
                  placeholder="9876543210"
                  sx={{ mb: 3 }}
                />

                <Button
                  fullWidth
                  variant="contained"
                  onClick={handleSendOTP}
                  disabled={loading || phone.length !== 10}
                  startIcon={loading ? <CircularProgress size={20} /> : <Phone />}
                  sx={{
                    py: 1.5,
                    bgcolor: '#FFB300',
                    color: '#000',
                    '&:hover': { bgcolor: '#FFA000' },
                    '&:disabled': { bgcolor: '#ccc' }
                  }}
                >
                  {loading ? 'Sending...' : 'Send OTP'}
                </Button>
              </Box>
            ) : (
              // OTP Verification Screen
              <Box>
                <Alert severity="success" sx={{ mb: 3, borderRadius: 1 }}>
                  OTP sent to +91 {phone}
                </Alert>

                <TextField
                  fullWidth
                  label="Enter OTP"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value.replace(/\D/g, ''))}
                  disabled={loading}
                  inputProps={{ maxLength: 6 }}
                  placeholder="123456"
                  sx={{ mb: 2 }}
                />

                <Button
                  fullWidth
                  variant="contained"
                  onClick={handleVerifyOTP}
                  disabled={loading || otp.length !== 6}
                  startIcon={loading ? <CircularProgress size={20} /> : <VerifiedIcon />}
                  sx={{
                    py: 1.5,
                    bgcolor: '#FFB300',
                    color: '#000',
                    mb: 2,
                    '&:hover': { bgcolor: '#FFA000' },
                    '&:disabled': { bgcolor: '#ccc' }
                  }}
                >
                  {loading ? 'Verifying...' : 'Verify OTP'}
                </Button>

                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Button
                    onClick={() => {
                      setOtpSent(false);
                      setOtp('');
                    }}
                    sx={{ color: '#FFB300' }}
                  >
                    Change Number
                  </Button>

                  <Button
                    onClick={handleResendOTP}
                    disabled={countdown > 0 || loading}
                    sx={{ color: countdown > 0 ? 'text.secondary' : '#FFB300' }}
                  >
                    {countdown > 0 ? `Resend in ${countdown}s` : 'Resend OTP'}
                  </Button>
                </Box>
              </Box>
            )}
          </CardContent>
        </Paper>
      </Box>
    </Container>
  );
};

export default MobileLogin;