import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  Link,
  CircularProgress,
  Alert,
  InputAdornment
} from '@mui/material';
import { LocalShipping as TruckIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

const API_BASE_URL = import.meta.env.VITE_API_URL || 'https://godelivo.com';

export default function DriverLogin() {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [maskedPhone, setMaskedPhone] = useState('');

  const handleSendOtp = async () => {
    if (!phone || phone.length !== 10) {
      setError('Please enter a valid 10-digit phone number');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_BASE_URL}/api/driver/send-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phoneNumber: `+91${phone}` })
      });

      const data = await response.json();

      if (response.ok) {
        setMaskedPhone(`+91 ${phone.slice(0, 5)} ${phone.slice(5)}`);
        setStep(2);
      } else {
        setError(data.message || 'Failed to send OTP. Please try again.');
      }
    } catch (err) {
      setError('Network error. Please check your connection and try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (!otp || otp.length !== 6) {
      setError('Please enter a valid 6-digit OTP');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_BASE_URL}/api/driver/verify-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phoneNumber: `+91${phone}`, otp })
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem('driverToken', data.token);
        localStorage.setItem('driverId', data.driverId);
        navigate('/driver-dashboard');
      } else {
        setError(data.message || 'Invalid OTP. Please try again.');
      }
    } catch (err) {
      setError('Network error. Please check your connection and try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleResendOtp = async () => {
    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_BASE_URL}/api/driver/send-otp`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phoneNumber: `+91${phone}` })
      });

      const data = await response.json();

      if (response.ok) {
        setError('');
      } else {
        setError(data.message || 'Failed to resend OTP. Please try again.');
      }
    } catch (err) {
      setError('Network error. Please check your connection and try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#f5f5f5',
        p: 2
      }}
    >
      <Card sx={{ maxWidth: 400, width: '100%', boxShadow: 3 }}>
        <CardContent sx={{ p: 4, textAlign: 'center' }}>
          <Box
            sx={{
              width: 64,
              height: 64,
              borderRadius: '50%',
              backgroundColor: '#FFB300',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 16px'
            }}
          >
            <TruckIcon sx={{ color: 'white', fontSize: 32 }} />
          </Box>

          <Typography variant="h5" component="h1" gutterBottom fontWeight="600">
            Driver Login
          </Typography>

          <Typography variant="body2" color="text.secondary" gutterBottom>
            {step === 1
              ? 'Enter your registered phone number'
              : `Enter OTP sent to ${maskedPhone}`}
          </Typography>

          {error && (
            <Alert severity="error" sx={{ mt: 2, mb: 2 }}>
              {error}
            </Alert>
          )}

          {step === 1 ? (
            <Box sx={{ mt: 3 }}>
              <TextField
                fullWidth
                label="Phone Number"
                variant="outlined"
                value={phone}
                onChange={(e) => {
                  const value = e.target.value.replace(/\D/g, '').slice(0, 10);
                  setPhone(value);
                }}
                placeholder="9876543210"
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">+91</InputAdornment>
                  )
                }}
                sx={{ mb: 2 }}
              />

              <Button
                fullWidth
                variant="contained"
                onClick={handleSendOtp}
                disabled={loading || phone.length !== 10}
                sx={{
                  backgroundColor: '#FFB300',
                  '&:hover': { backgroundColor: '#FFA000' },
                  py: 1.5,
                  textTransform: 'none',
                  fontSize: '1rem'
                }}
              >
                {loading ? (
                  <CircularProgress size={24} color="inherit" />
                ) : (
                  'Send OTP'
                )}
              </Button>

              <Box sx={{ mt: 3 }}>
                <Link
                  href="/driver-status"
                  underline="hover"
                  color="text.secondary"
                  sx={{ fontSize: '0.875rem' }}
                >
                  Check Application Status
                </Link>
              </Box>
            </Box>
          ) : (
            <Box sx={{ mt: 3 }}>
              <TextField
                fullWidth
                label="OTP"
                variant="outlined"
                value={otp}
                onChange={(e) => {
                  const value = e.target.value.replace(/\D/g, '').slice(0, 6);
                  setOtp(value);
                }}
                placeholder="123456"
                inputProps={{ maxLength: 6 }}
                sx={{ mb: 2 }}
              />

              <Button
                fullWidth
                variant="contained"
                onClick={handleVerifyOtp}
                disabled={loading || otp.length !== 6}
                sx={{
                  backgroundColor: '#FFB300',
                  '&:hover': { backgroundColor: '#FFA000' },
                  py: 1.5,
                  textTransform: 'none',
                  fontSize: '1rem'
                }}
              >
                {loading ? (
                  <CircularProgress size={24} color="inherit" />
                ) : (
                  'Verify OTP'
                )}
              </Button>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'center', gap: 2 }}>
                <Link
                  component="button"
                  variant="body2"
                  onClick={handleResendOtp}
                  disabled={loading}
                  underline="hover"
                  sx={{ color: '#FFB300', fontWeight: 500 }}
                >
                  Resend OTP
                </Link>
                <Link
                  component="button"
                  variant="body2"
                  onClick={() => setStep(1)}
                  underline="hover"
                  sx={{ color: 'text.secondary' }}
                >
                  Change Number
                </Link>
              </Box>
            </Box>
          )}
        </CardContent>
      </Card>
    </Box>
  );
}
