import React, { useState, useEffect } from 'react'
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Avatar,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Pagination,
  Stepper,
  Step,
  StepLabel,
  TextField,
} from '@mui/material'
import {
  Add as AddIcon,
  Visibility as ViewIcon,
  AssignmentInd as AssignIcon,
  Cancel as CancelIcon,
} from '@mui/icons-material'
import apiService from '../services/api'

const steps = ['Pending', 'Assigned', 'Accepted', 'Picked Up', 'In Progress', 'Completed']

const Orders = () => {
  const [orders, setOrders] = useState([])
  const [drivers, setDrivers] = useState([])
  const [loading, setLoading] = useState(true)
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [filter, setFilter] = useState('')
  const [selectedOrder, setSelectedOrder] = useState(null)
  const [assignDialogOpen, setAssignDialogOpen] = useState(false)
  const [selectedDriver, setSelectedDriver] = useState('')
  const [viewDialogOpen, setViewDialogOpen] = useState(false)
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false)
  const [cancelReason, setCancelReason] = useState('')

  useEffect(() => {
    fetchOrders()
    fetchAvailableDrivers()
  }, [page, filter])

  const fetchOrders = async () => {
    try {
      const params = { page, limit: 10 }
      if (filter) params.status = filter
      
      const response = await apiService.getOrders(params)
      setOrders(response.data || [])
      setTotalPages(response.pagination?.pages || 1)
    } catch (error) {
      console.error('Error fetching orders:', error)
    } finally {
      setLoading(false)
    }
  }

  const fetchAvailableDrivers = async () => {
    try {
      const response = await apiService.getAvailableDrivers()
      setDrivers(response.data || [])
    } catch (error) {
      console.error('Error fetching drivers:', error)
    }
  }

  const handleAssignDriver = async () => {
    if (!selectedDriver || !selectedOrder) return
    
    try {
      await apiService.assignDriver(selectedOrder._id, selectedDriver)
      setAssignDialogOpen(false)
      setSelectedDriver('')
      setSelectedOrder(null)
      fetchOrders()
    } catch (error) {
      console.error('Error assigning driver:', error)
      alert(error.message)
    }
  }

  const handleCancelOrder = async () => {
    if (!selectedOrder) return
    
    try {
      await apiService.cancelOrder(selectedOrder._id, cancelReason)
      setCancelDialogOpen(false)
      setCancelReason('')
      setSelectedOrder(null)
      fetchOrders()
    } catch (error) {
      console.error('Error cancelling order:', error)
      alert(error.message)
    }
  }

  const getStatusColor = (status) => {
    const colors = {
      pending: 'warning',
      assigned: 'info',
      accepted: 'success',
      picked_up: 'primary',
      in_progress: 'primary',
      completed: 'success',
      cancelled: 'error',
    }
    return colors[status] || 'default'
  }

  const getActiveStep = (status) => {
    const statusMap = {
      pending: 0,
      assigned: 1,
      accepted: 2,
      picked_up: 3,
      in_progress: 4,
      completed: 5,
    }
    return statusMap[status] || 0
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
        <Box>
          <Typography variant="h4" sx={{ fontWeight: 700, mb: 0.5 }}>
            Orders
          </Typography>
          <Typography variant="body1" sx={{ color: 'text.secondary' }}>
            Manage and track all bookings
          </Typography>
        </Box>
      </Box>

      <Card>
        <CardContent sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
            <FormControl sx={{ minWidth: 150 }}>
              <InputLabel>Status</InputLabel>
              <Select value={filter} onChange={(e) => setFilter(e.target.value)} label="Status">
                <MenuItem value="">All</MenuItem>
                <MenuItem value="pending">Pending</MenuItem>
                <MenuItem value="assigned">Assigned</MenuItem>
                <MenuItem value="accepted">Accepted</MenuItem>
                <MenuItem value="in_progress">In Progress</MenuItem>
                <MenuItem value="completed">Completed</MenuItem>
                <MenuItem value="cancelled">Cancelled</MenuItem>
              </Select>
            </FormControl>
          </Box>

          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Booking ID</TableCell>
                  <TableCell>Customer</TableCell>
                  <TableCell>Driver</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Fare</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {orders.map((order) => (
                  <TableRow key={order._id} hover>
                    <TableCell>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        #{order.bookingId}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <Avatar sx={{ width: 32, height: 32, mr: 1, bgcolor: 'primary.light' }}>
                          {order.customerId?.name?.charAt(0) || 'C'}
                        </Avatar>
                        <Box>
                          <Typography variant="body2" sx={{ fontWeight: 500 }}>
                            {order.customerId?.name || 'Unknown'}
                          </Typography>
                          <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                            {order.customerId?.phone}
                          </Typography>
                        </Box>
                      </Box>
                    </TableCell>
                    <TableCell>
                      {order.driverId ? (
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Avatar sx={{ width: 28, height: 28, mr: 1, bgcolor: 'success.light' }}>
                            {order.driverId.name?.charAt(0)}
                          </Avatar>
                          <Typography variant="body2">{order.driverId.name}</Typography>
                        </Box>
                      ) : (
                        <Chip label="Not Assigned" size="small" color="default" />
                      )}
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={order.status}
                        color={getStatusColor(order.status)}
                        size="small"
                        sx={{ textTransform: 'capitalize', fontWeight: 500 }}
                      />
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                         ₹{order.fare?.total?.toFixed(2) || '0.00'}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={() => {
                          setSelectedOrder(order)
                          setViewDialogOpen(true)
                        }}
                      >
                        <ViewIcon />
                      </IconButton>
                      {order.status === 'pending' && (
                        <IconButton
                          size="small"
                          color="primary"
                          onClick={() => {
                            setSelectedOrder(order)
                            setAssignDialogOpen(true)
                          }}
                        >
                          <AssignIcon />
                        </IconButton>
                      )}
                      {order.status !== 'completed' && order.status !== 'cancelled' && (
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => {
                            setSelectedOrder(order)
                            setCancelDialogOpen(true)
                          }}
                        >
                          <CancelIcon />
                        </IconButton>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
                {orders.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={6} align="center" sx={{ py: 4 }}>
                      <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                        No orders found
                      </Typography>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
            <Pagination count={totalPages} page={page} onChange={(e, p) => setPage(p)} color="primary" />
          </Box>
        </CardContent>
      </Card>

      {/* Assign Driver Dialog */}
      <Dialog open={assignDialogOpen} onClose={() => setAssignDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Assign Driver</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 2 }}>
            Booking #{selectedOrder?.bookingId}
          </Typography>
          <FormControl fullWidth>
            <InputLabel>Select Driver</InputLabel>
            <Select value={selectedDriver} onChange={(e) => setSelectedDriver(e.target.value)} label="Select Driver">
              {drivers.map((driver) => (
                <MenuItem key={driver._id} value={driver._id}>
                  {driver.name} - {driver.vehicleType}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAssignDialogOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleAssignDriver} disabled={!selectedDriver}>
            Assign
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Order Dialog */}
      <Dialog open={viewDialogOpen} onClose={() => setViewDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Order Details</DialogTitle>
        <DialogContent>
          {selectedOrder && (
            <Box sx={{ mt: 2 }}>
              <Stepper activeStep={getActiveStep(selectedOrder.status)} alternativeLabel>
                {steps.map((label) => (
                  <Step key={label}>
                    <StepLabel>{label}</StepLabel>
                  </Step>
                ))}
              </Stepper>

              <Box sx={{ mt: 4 }}>
                <Typography variant="h6" sx={{ mb: 2 }}>
                  Booking #{selectedOrder.bookingId}
                </Typography>
                
                <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 3 }}>
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Customer
                    </Typography>
                    <Typography variant="body1" sx={{ fontWeight: 500 }}>
                      {selectedOrder.customerId?.name}
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                      {selectedOrder.customerId?.phone}
                    </Typography>
                  </Box>
                  
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Driver
                    </Typography>
                    <Typography variant="body1" sx={{ fontWeight: 500 }}>
                      {selectedOrder.driverId?.name || 'Not Assigned'}
                    </Typography>
                  </Box>
                  
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Pickup Location
                    </Typography>
                    <Typography variant="body1">
                      {selectedOrder.locations?.pickup?.address}
                    </Typography>
                  </Box>
                  
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Dropoff Location
                    </Typography>
                    <Typography variant="body1">
                      {selectedOrder.locations?.dropoff?.address}
                    </Typography>
                  </Box>
                  
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Vehicle Type
                    </Typography>
                    <Typography variant="body1">{selectedOrder.vehicleType}</Typography>
                  </Box>
                  
                  <Box>
                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                      Total Fare
                    </Typography>
                    <Typography variant="h6" sx={{ fontWeight: 700, color: 'primary.main' }}>
                       ₹{selectedOrder.fare?.total?.toFixed(2)}
                    </Typography>
                  </Box>
                </Box>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Cancel Order Dialog */}
      <Dialog open={cancelDialogOpen} onClose={() => setCancelDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Cancel Order</DialogTitle>
        <DialogContent>
          <Typography variant="body2" sx={{ mb: 2 }}>
            Are you sure you want to cancel order #{selectedOrder?.bookingId}?
          </Typography>
          <TextField
            fullWidth
            multiline
            rows={3}
            label="Reason for cancellation (optional)"
            value={cancelReason}
            onChange={(e) => setCancelReason(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCancelDialogOpen(false)}>Cancel</Button>
          <Button variant="contained" color="error" onClick={handleCancelOrder}>
            Confirm Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}

export default Orders