import { io } from 'socket.io-client';

const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'https://godelivo.com';

class DriverSocketService {
  constructor() {
    this.socket = null;
    this.driverId = null;
    this.listeners = new Map();
  }

  connect(driverId) {
    if (this.socket?.connected && this.driverId === driverId) {
      return this.socket;
    }

    this.driverId = driverId;
    this.socket = io(`${SOCKET_URL}/drivers`, {
      transports: ['websocket'],
      autoConnect: true,
    });

    this.socket.on('connect', () => {
      console.log('Driver socket connected:', this.socket.id);
      this.emitJoin(driverId);
    });

    this.socket.on('disconnect', (reason) => {
      console.log('Driver socket disconnected:', reason);
    });

    this.socket.on('connect_error', (error) => {
      console.error('Driver socket connection error:', error);
    });

    return this.socket;
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
      this.driverId = null;
      this.listeners.clear();
    }
  }

  emitJoin(driverId) {
    if (this.socket?.connected) {
      this.socket.emit('driver:join', driverId);
    }
  }

  emitLocationUpdate(driverId, latitude, longitude) {
    if (this.socket?.connected) {
      this.socket.emit('driver:location-update', {
        driverId,
        latitude,
        longitude,
      });
    }
  }

  emitAvailabilityUpdate(driverId, isAvailable) {
    if (this.socket?.connected) {
      this.socket.emit('driver:availability-update', {
        driverId,
        isAvailable,
      });
    }
  }

  on(event, callback) {
    if (this.socket) {
      this.socket.on(event, callback);
      if (!this.listeners.has(event)) {
        this.listeners.set(event, []);
      }
      this.listeners.get(event).push(callback);
    }
  }

  off(event, callback) {
    if (this.socket) {
      if (callback) {
        this.socket.off(event, callback);
        const callbacks = this.listeners.get(event);
        if (callbacks) {
          const index = callbacks.indexOf(callback);
          if (index > -1) {
            callbacks.splice(index, 1);
          }
        }
      } else {
        this.socket.off(event);
        this.listeners.delete(event);
      }
    }
  }

  isConnected() {
    return this.socket?.connected || false;
  }

  getSocketId() {
    return this.socket?.id || null;
  }
}

const driverSocketService = new DriverSocketService();
export default driverSocketService;
