import React, { useState } from 'react';
import {
  Box,
  Button,
  Typography,
  TextField,
  Paper,
  Grid,
  Card,
  CardContent,
  InputAdornment,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Alert,
  Divider,
  Chip,
  Stepper,
  Step,
  StepLabel,
} from '@mui/material';
import {
  CloudUpload,
  Delete,
  Phone,
  Person,
  Email,
  Home,
  DirectionsCar,
  AccountBalance,
  PhotoCamera,
  CheckCircle,
} from '@mui/icons-material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import toast from 'react-hot-toast';
import axios from 'axios';

const API_BASE_URL = 'https://godelivo.com';

const initialFormData = {
  // Phone Verification
  phone: '',
  otp: '',
  
  // Personal Info
  fullName: '',
  email: '',
  dateOfBirth: null,
  address: '',
  city: '',
  state: '',
  pincode: '',
  
  // Vehicle Info
  vehicleType: '',
  vehicleNumber: '',
  vehicleModel: '',
  vehicleYear: '',
  vehicleColor: '',
  
  // Bank Info
  accountHolderName: '',
  accountNumber: '',
  ifscCode: '',
  bankName: '',
  branchName: '',
  
  // Document Numbers
  aadharNumber: '',
  licenseNumber: '',
  rcNumber: '',
  
  // Files - Aadhar now has front and back
  profilePhoto: null,
  aadharFront: null,
  aadharBack: null,
  panCard: null,
  drivingLicense: null,
  vehicleRC: null,
  vehiclePhoto: null,
  
  // Track upload status
  uploadStatus: {
    profilePhoto: false,
    aadharFront: false,
    aadharBack: false,
    panCard: false,
    drivingLicense: false,
    vehicleRC: false,
    vehiclePhoto: false,
  }
};

const DriverSignup = () => {
  const [step, setStep] = useState('otp');
  const [loading, setLoading] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [tempToken, setTempToken] = useState(localStorage.getItem('tempToken') || '');
  const [formData, setFormData] = useState(initialFormData);
  const [activeStep, setActiveStep] = useState(0);
  
  console.log(tempToken);

  const vehicleTypes = [
    'Bike', 'Scooter', 'Auto Rickshaw', 'Mini Truck', 'Pickup Truck', 'Truck'
  ];

  const registrationSteps = [
    'Personal Info',
    'Identity Documents',
    'Vehicle Details',
    'Bank Details',
    'Review'
  ];

  // Handle text input changes
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Handle file upload
  const handleFileChange = (e, fieldName) => {
    const file = e.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please upload an image file');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error('File size should be less than 5MB');
      return;
    }

    setFormData(prev => ({
      ...prev,
      [fieldName]: file,
      uploadStatus: {
        ...prev.uploadStatus,
        [fieldName]: true
      }
    }));
  };

  // Remove file
  const removeFile = (fieldName) => {
    setFormData(prev => ({
      ...prev,
      [fieldName]: null,
      uploadStatus: {
        ...prev.uploadStatus,
        [fieldName]: false
      }
    }));
  };

  // Send OTP
  const handleSendOTP = async () => {
    if (formData.phone.length !== 10) {
      toast.error('Please enter a valid 10-digit phone number');
      return;
    }

    setLoading(true);
    try {
      const response = await axios.post(`${API_BASE_URL}/api/driver/send-otp`, {
        phone: formData.phone
      });
      
      if (response.data.success) {
        setOtpSent(true);
        toast.success('OTP sent successfully!');
        if (response.data.data?.otp) {
          console.log('OTP for testing:', response.data.data.otp);
        }
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to send OTP');
    } finally {
      setLoading(false);
    }
  };

  // Verify OTP
  const handleVerifyOTP = async () => {
    if (formData.otp.length !== 6) {
      toast.error('Please enter a valid 6-digit OTP');
      return;
    }

    setLoading(true);
    try {
      const response = await axios.post(`${API_BASE_URL}/api/driver/verify-otp`, {
        phone: formData.phone,
        otp: formData.otp
      });
      
      if (response.data.success) {
        localStorage.setItem('tempToken', response.data.data.tempToken);
        setTempToken(response.data.data.tempToken);
        toast.success('Phone verified successfully!');
        setStep('registration');
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Invalid OTP');
    } finally {
      setLoading(false);
    }
  };

  // Validate current step
  const validateStep = (step) => {
    switch(step) {
      case 0: // Personal Info
        if (!formData.fullName) return 'Full name is required';
        if (!formData.email || !formData.email.includes('@')) return 'Valid email is required';
        if (!formData.dateOfBirth) return 'Date of birth is required';
        if (!formData.address) return 'Address is required';
        if (!formData.city) return 'City is required';
        if (!formData.state) return 'State is required';
        if (!formData.pincode) return 'Pincode is required';
        return null;
        
      case 1: // Identity Documents
        if (!formData.profilePhoto) return 'Profile photo is required';
        if (!formData.aadharFront) return 'Aadhar front image is required';
        if (!formData.aadharBack) return 'Aadhar back image is required';
        if (!formData.panCard) return 'PAN card is required';
        if (!formData.drivingLicense) return 'Driving license is required';
        if (!formData.aadharNumber) return 'Aadhar number is required';
        if (!formData.licenseNumber) return 'License number is required';
        return null;
        
      case 2: // Vehicle Details
        if (!formData.vehicleType) return 'Vehicle type is required';
        if (!formData.vehicleNumber) return 'Vehicle number is required';
        if (!formData.vehicleRC) return 'Vehicle RC is required';
        if (!formData.vehiclePhoto) return 'Vehicle photo is required';
        if (!formData.rcNumber) return 'RC number is required';
        return null;
        
      case 3: // Bank Details
        if (!formData.accountHolderName) return 'Account holder name is required';
        if (!formData.accountNumber) return 'Account number is required';
        if (!formData.ifscCode) return 'IFSC code is required';
        if (!formData.bankName) return 'Bank name is required';
        return null;
        
      default:
        return null;
    }
  };

  // Handle next step
  const handleNext = () => {
    const error = validateStep(activeStep);
    if (error) {
      toast.error(error);
      return;
    }
    setActiveStep((prev) => prev + 1);
  };

  // Handle back step
  const handleBack = () => {
    setActiveStep((prev) => prev - 1);
  };

  // Validate all fields before submission
  const validateForm = () => {
    for (let i = 0; i < 4; i++) {
      const error = validateStep(i);
      if (error) return error;
    }
    return null;
  };

  // Submit complete registration
  const handleSubmit = async () => {
    const error = validateForm();
    if (error) {
      toast.error(error);
      return;
    }

    setLoading(true);
    
    try {
      const formDataToSend = new FormData();
      
      // Append all text fields
      formDataToSend.append('fullName', formData.fullName);
      formDataToSend.append('email', formData.email);
      formDataToSend.append('dateOfBirth', formData.dateOfBirth.toISOString());
      
      // Address as JSON
      const addressObj = {
        street: formData.address,
        city: formData.city,
        state: formData.state,
        pincode: formData.pincode
      };
      formDataToSend.append('address', JSON.stringify(addressObj));
      
      // Vehicle details
      formDataToSend.append('vehicleType', formData.vehicleType);
      formDataToSend.append('vehicleNumber', formData.vehicleNumber);
      formDataToSend.append('vehicleModel', formData.vehicleModel || '');
      formDataToSend.append('vehicleYear', formData.vehicleYear || '');
      formDataToSend.append('vehicleColor', formData.vehicleColor || '');
      
      // Bank details
      formDataToSend.append('accountHolderName', formData.accountHolderName);
      formDataToSend.append('accountNumber', formData.accountNumber);
      formDataToSend.append('ifscCode', formData.ifscCode);
      formDataToSend.append('bankName', formData.bankName);
      formDataToSend.append('branchName', formData.branchName || '');
      
      // Document numbers
      formDataToSend.append('aadharNumber', formData.aadharNumber);
      formDataToSend.append('licenseNumber', formData.licenseNumber);
      formDataToSend.append('rcNumber', formData.rcNumber);

      // Append all files - Note: aadharFront and aadharBack are separate
      formDataToSend.append('profilePhoto', formData.profilePhoto);
      formDataToSend.append('aadharFront', formData.aadharFront);
      formDataToSend.append('aadharBack', formData.aadharBack);
      formDataToSend.append('panCard', formData.panCard);
      formDataToSend.append('drivingLicense', formData.drivingLicense);
      formDataToSend.append('vehicleRC', formData.vehicleRC);
      formDataToSend.append('vehiclePhoto', formData.vehiclePhoto);

      const response = await axios.post(
        `${API_BASE_URL}/api/driver/register`,
        formDataToSend,
        {
          headers: {
            'Authorization': `Bearer ${tempToken}`,
            'Content-Type': 'multipart/form-data'
          }
        }
      );

      if (response.data.success) {
        toast.success('Registration successful! Your application is under review.');
        
        // Show document status if available
        if (response.data.data?.documentStatus) {
          console.log('Document verification status:', response.data.data.documentStatus);
        }
        
        // Clear form and token
        localStorage.removeItem('tempToken');
        setFormData(initialFormData);
        setStep('otp');
        setOtpSent(false);
        setTempToken('');
        setActiveStep(0);
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  // File input component with status indicator
  const FileInput = ({ label, field, required = true }) => (
    <Box sx={{ mb: 2 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
        <Typography variant="body2" fontWeight="500">
          {label} {required && '*'}
        </Typography>
        {formData.uploadStatus[field] && (
          <Chip
            size="small"
            icon={<CheckCircle sx={{ fontSize: 14 }} />}
            label="Uploaded"
            color="success"
            variant="outlined"
          />
        )}
      </Box>
      <Box
        sx={{
          border: '2px dashed',
          borderColor: formData[field] ? '#4caf50' : '#ccc',
          borderRadius: 1,
          p: 2,
          textAlign: 'center',
          bgcolor: formData[field] ? '#f1f8e9' : '#fafafa',
          transition: 'all 0.3s',
          '&:hover': {
            borderColor: '#FFB300',
            bgcolor: 'rgba(255, 179, 0, 0.05)',
          },
        }}
      >
        {formData[field] ? (
          <Box>
            <Typography variant="body2" color="success.main" gutterBottom>
              ✓ {formData[field].name}
            </Typography>
            <Button
              size="small"
              color="error"
              startIcon={<Delete />}
              onClick={() => removeFile(field)}
            >
              Remove
            </Button>
          </Box>
        ) : (
          <Button
            component="label"
            startIcon={<CloudUpload />}
            variant="outlined"
            sx={{ borderColor: '#FFB300', color: '#FFB300' }}
          >
            Choose File
            <input
              type="file"
              hidden
              accept="image/*"
              onChange={(e) => handleFileChange(e, field)}
            />
          </Button>
        )}
      </Box>
    </Box>
  );

  // OTP Verification Screen
  if (step === 'otp') {
    return (
      <LocalizationProvider dateAdapter={AdapterDateFns}>
        <Box sx={{ minHeight: '100vh', bgcolor: '#f5f5f5', display: 'flex', alignItems: 'center', py: 4 }}>
          <Paper sx={{ maxWidth: 400, mx: 'auto', p: 4, width: '100%' }}>
            <Typography variant="h5" align="center" gutterBottom fontWeight="600" sx={{ color: '#FFB300' }}>
              Driver Registration
            </Typography>
            <Typography variant="body2" align="center" color="textSecondary" sx={{ mb: 4 }}>
              Verify your phone number to continue
            </Typography>

            <TextField
              fullWidth
              label="Phone Number"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              disabled={otpSent}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Typography fontWeight="600" color="#FFB300">+91</Typography>
                  </InputAdornment>
                ),
              }}
              inputProps={{ maxLength: 10 }}
              sx={{ mb: 2 }}
            />

            {!otpSent ? (
              <Button
                fullWidth
                variant="contained"
                onClick={handleSendOTP}
                disabled={loading || formData.phone.length !== 10}
                startIcon={loading ? <CircularProgress size={20} /> : <Phone />}
                sx={{ bgcolor: '#FFB300', color: '#000', py: 1.5 }}
              >
                {loading ? 'Sending...' : 'Send OTP'}
              </Button>
            ) : (
              <>
                <Alert severity="success" sx={{ mb: 2 }}>
                  OTP sent to +91 {formData.phone}
                </Alert>
                <TextField
                  fullWidth
                  label="Enter OTP"
                  name="otp"
                  value={formData.otp}
                  onChange={handleChange}
                  inputProps={{ maxLength: 6 }}
                  sx={{ mb: 2 }}
                />
                <Button
                  fullWidth
                  variant="contained"
                  onClick={handleVerifyOTP}
                  disabled={loading || formData.otp.length !== 6}
                  startIcon={loading ? <CircularProgress size={20} /> : <CheckCircle />}
                  sx={{ bgcolor: '#FFB300', color: '#000', py: 1.5 }}
                >
                  {loading ? 'Verifying...' : 'Verify OTP'}
                </Button>
                <Button
                  fullWidth
                  onClick={() => {
                    setOtpSent(false);
                    setFormData(prev => ({ ...prev, otp: '' }));
                  }}
                  sx={{ mt: 1, color: '#FFB300' }}
                >
                  Change Phone Number
                </Button>
              </>
            )}
          </Paper>
        </Box>
      </LocalizationProvider>
    );
  }

  // Registration Form with Steps
  return (
    <LocalizationProvider dateAdapter={AdapterDateFns}>
      <Box sx={{ minHeight: '100vh', bgcolor: '#f5f5f5', py: 4, px: 2 }}>
        <Paper sx={{ maxWidth: 1000, mx: 'auto', p: 3 }}>
          <Typography variant="h5" align="center" gutterBottom fontWeight="600" sx={{ color: '#FFB300', mb: 3 }}>
            Complete Your Registration
          </Typography>

          <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
            {registrationSteps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>

          {/* Step 0: Personal Information */}
          {activeStep === 0 && (
            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                  <Person sx={{ mr: 1, verticalAlign: 'middle' }} /> Personal Information
                </Typography>
                
                <Grid container spacing={2}>
                  <Grid item xs={12} md={4}>
                    <FileInput label="Profile Photo" field="profilePhoto" />
                  </Grid>
                  
                  <Grid item xs={12} md={8}>
                    <Grid container spacing={2}>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          fullWidth
                          label="Full Name *"
                          name="fullName"
                          value={formData.fullName}
                          onChange={handleChange}
                          size="small"
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          fullWidth
                          label="Email *"
                          name="email"
                          type="email"
                          value={formData.email}
                          onChange={handleChange}
                          size="small"
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <DatePicker
                          label="Date of Birth *"
                          value={formData.dateOfBirth}
                          onChange={(date) => setFormData({ ...formData, dateOfBirth: date })}
                          slotProps={{ textField: { size: 'small', fullWidth: true } }}
                        />
                      </Grid>
                    </Grid>
                  </Grid>

                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="Street Address *"
                      name="address"
                      value={formData.address}
                      onChange={handleChange}
                      multiline
                      rows={2}
                      size="small"
                    />
                  </Grid>
                  
                  <Grid item xs={12} sm={4}>
                    <TextField
                      fullWidth
                      label="City *"
                      name="city"
                      value={formData.city}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      fullWidth
                      label="State *"
                      name="state"
                      value={formData.state}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      fullWidth
                      label="Pincode *"
                      name="pincode"
                      value={formData.pincode}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          )}

          {/* Step 1: Identity Documents */}
          {activeStep === 1 && (
            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                  <PhotoCamera sx={{ mr: 1, verticalAlign: 'middle' }} /> Identity Documents
                </Typography>
                
                <Grid container spacing={3}>
                  <Grid item xs={12} md={6}>
                    <FileInput label="Aadhar Card (Front)" field="aadharFront" />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <FileInput label="Aadhar Card (Back)" field="aadharBack" />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      size="small"
                      label="Aadhar Number *"
                      name="aadharNumber"
                      value={formData.aadharNumber}
                      onChange={handleChange}
                    />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <FileInput label="PAN Card" field="panCard" />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <FileInput label="Driving License" field="drivingLicense" />
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <TextField
                      fullWidth
                      size="small"
                      label="License Number *"
                      name="licenseNumber"
                      value={formData.licenseNumber}
                      onChange={handleChange}
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          )}

          {/* Step 2: Vehicle Details */}
          {activeStep === 2 && (
            <>
              <Card sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                    <DirectionsCar sx={{ mr: 1, verticalAlign: 'middle' }} /> Vehicle Information
                  </Typography>
                  
                  <Grid container spacing={3}>
                    <Grid item xs={12} md={4}>
                      <FileInput label="Vehicle Photo" field="vehiclePhoto" />
                    </Grid>
                    
                    <Grid item xs={12} md={8}>
                      <Grid container spacing={2}>
                        <Grid item xs={12} sm={6}>
                          <FormControl fullWidth size="small">
                            <InputLabel>Vehicle Type *</InputLabel>
                            <Select
                              name="vehicleType"
                              value={formData.vehicleType}
                              onChange={handleChange}
                              label="Vehicle Type *"
                            >
                              {vehicleTypes.map(type => (
                                <MenuItem key={type} value={type}>{type}</MenuItem>
                              ))}
                            </Select>
                          </FormControl>
                        </Grid>
                        <Grid item xs={12} sm={6}>
                          <TextField
                            fullWidth
                            label="Vehicle Number *"
                            name="vehicleNumber"
                            value={formData.vehicleNumber}
                            onChange={handleChange}
                            size="small"
                            placeholder="MH12AB1234"
                          />
                        </Grid>
                        <Grid item xs={12} sm={4}>
                          <TextField
                            fullWidth
                            label="Model"
                            name="vehicleModel"
                            value={formData.vehicleModel}
                            onChange={handleChange}
                            size="small"
                          />
                        </Grid>
                        <Grid item xs={12} sm={4}>
                          <TextField
                            fullWidth
                            label="Year"
                            name="vehicleYear"
                            value={formData.vehicleYear}
                            onChange={handleChange}
                            size="small"
                          />
                        </Grid>
                        <Grid item xs={12} sm={4}>
                          <TextField
                            fullWidth
                            label="Color"
                            name="vehicleColor"
                            value={formData.vehicleColor}
                            onChange={handleChange}
                            size="small"
                          />
                        </Grid>
                      </Grid>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>

              <Card sx={{ mb: 3 }}>
                <CardContent>
                  <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                    Vehicle Documents
                  </Typography>
                  
                  <Grid container spacing={3}>
                    <Grid item xs={12} md={6}>
                      <FileInput label="Vehicle RC" field="vehicleRC" />
                      <TextField
                        fullWidth
                        size="small"
                        label="RC Number *"
                        name="rcNumber"
                        value={formData.rcNumber}
                        onChange={handleChange}
                        sx={{ mt: 1 }}
                      />
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            </>
          )}

          {/* Step 3: Bank Details */}
          {activeStep === 3 && (
            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                  <AccountBalance sx={{ mr: 1, verticalAlign: 'middle' }} /> Bank Details
                </Typography>
                
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Account Holder Name *"
                      name="accountHolderName"
                      value={formData.accountHolderName}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Account Number *"
                      name="accountNumber"
                      value={formData.accountNumber}
                      onChange={handleChange}
                      size="small"
                      type="password"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="IFSC Code *"
                      name="ifscCode"
                      value={formData.ifscCode}
                      onChange={handleChange}
                      size="small"
                      placeholder="HDFC0001234"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Bank Name *"
                      name="bankName"
                      value={formData.bankName}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="Branch Name"
                      name="branchName"
                      value={formData.branchName}
                      onChange={handleChange}
                      size="small"
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          )}

          {/* Step 4: Review */}
          {activeStep === 4 && (
            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: '#FFB300', borderBottom: '1px solid #FFB300', pb: 1 }}>
                  <CheckCircle sx={{ mr: 1, verticalAlign: 'middle' }} /> Review Your Information
                </Typography>
                
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2" gutterBottom>Personal Information</Typography>
                    <Typography variant="body2">Name: {formData.fullName}</Typography>
                    <Typography variant="body2">Email: {formData.email}</Typography>
                    <Typography variant="body2">DOB: {formData.dateOfBirth?.toLocaleDateString()}</Typography>
                    <Typography variant="body2">Address: {formData.address}, {formData.city}, {formData.state} - {formData.pincode}</Typography>
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2" gutterBottom>Documents Uploaded</Typography>
                    {formData.uploadStatus.profilePhoto && <Typography variant="body2" color="success.main">✓ Profile Photo</Typography>}
                    {formData.uploadStatus.aadharFront && <Typography variant="body2" color="success.main">✓ Aadhar Front</Typography>}
                    {formData.uploadStatus.aadharBack && <Typography variant="body2" color="success.main">✓ Aadhar Back</Typography>}
                    {formData.uploadStatus.panCard && <Typography variant="body2" color="success.main">✓ PAN Card</Typography>}
                    {formData.uploadStatus.drivingLicense && <Typography variant="body2" color="success.main">✓ Driving License</Typography>}
                    {formData.uploadStatus.vehicleRC && <Typography variant="body2" color="success.main">✓ Vehicle RC</Typography>}
                    {formData.uploadStatus.vehiclePhoto && <Typography variant="body2" color="success.main">✓ Vehicle Photo</Typography>}
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2" gutterBottom>Vehicle Details</Typography>
                    <Typography variant="body2">Type: {formData.vehicleType}</Typography>
                    <Typography variant="body2">Number: {formData.vehicleNumber}</Typography>
                    <Typography variant="body2">Model: {formData.vehicleModel}</Typography>
                    <Typography variant="body2">Year: {formData.vehicleYear}</Typography>
                    <Typography variant="body2">Color: {formData.vehicleColor}</Typography>
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <Typography variant="subtitle2" gutterBottom>Bank Details</Typography>
                    <Typography variant="body2">Account Holder: {formData.accountHolderName}</Typography>
                    <Typography variant="body2">Account: ****{formData.accountNumber?.slice(-4)}</Typography>
                    <Typography variant="body2">IFSC: {formData.ifscCode}</Typography>
                    <Typography variant="body2">Bank: {formData.bankName}</Typography>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          )}

          <Divider sx={{ my: 3 }} />

          {/* Navigation Buttons */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Button
              variant="outlined"
              onClick={activeStep === 0 ? () => {
                setStep('otp');
                setOtpSent(false);
              } : handleBack}
              sx={{ borderColor: '#FFB300', color: '#FFB300' }}
            >
              {activeStep === 0 ? 'Back to OTP' : 'Back'}
            </Button>
            
            {activeStep === 4 ? (
              <Button
                variant="contained"
                size="large"
                onClick={handleSubmit}
                disabled={loading}
                startIcon={loading ? <CircularProgress size={20} /> : <CheckCircle />}
                sx={{ bgcolor: '#FFB300', color: '#000', px: 4, py: 1.5 }}
              >
                {loading ? 'Submitting...' : 'Submit Registration'}
              </Button>
            ) : (
              <Button
                variant="contained"
                onClick={handleNext}
                sx={{ bgcolor: '#FFB300', color: '#000', px: 4 }}
              >
                Next
              </Button>
            )}
          </Box>
        </Paper>
      </Box>
    </LocalizationProvider>
  );
};

export default DriverSignup;