import React from 'react';
import { Routes, Route } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import Layout from './components/Layout';
import PrivateRoute from './components/PrivateRoute';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Drivers from './pages/Drivers';
import Orders from './pages/Orders';
import Customers from './pages/Customers';
import Vehicles from './pages/Vehicles';
import Reports from './pages/Reports';
import UserStatus from './pages/UserStatus';
import Rides from './pages/Rides'
import Support from './pages/Support'
import DriverStatus from './pages/DriverStatus'
import SocketTest from './pages/SocketTest';
import DriverSignup from './pages/DriverSignup'
import DriverLogin from './pages/DriverLogin'
import DriverDashboard from './pages/DriverDashboard'
import DriverVerification from './pages/DriverVerification'
import MobileLogin from './pages/MobileLogin';
import CustomerSupport from './pages/CustomerSupport';
import PaymentTest from './pages/PaymentTestPage';
import NearbyDriversMap from './pages/NearbyDriversMap';
import DriverLocationSimulator from './pages/DriverLocationSimulator';
import WebhookTester from './pages/WebhookTester';
import PaymentTester from './pages/PaymentTester';
import LiveUPIPayment from './pages/LiveUPIPayment';

function App() {
  return (
    <>
      <Toaster
        position="top-right"
        toastOptions={{
          duration: 4000,
          style: {
            background: '#363636',
            color: '#fff',
            borderRadius: '12px',
          },
          success: {
            duration: 3000,
            iconTheme: {
              primary: '#2E7D32',
              secondary: '#fff',
            },
          },
          error: {
            duration: 4000,
            iconTheme: {
              primary: '#D32F2F',
              secondary: '#fff',
            },
          },
        }}
      />
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/driver-signup" element={<DriverSignup />} />
        <Route path="/driver-login" element={<DriverLogin />} />
        <Route path="/driver-dashboard" element={<DriverDashboard />} />
        <Route path="/mobile/login" element={<MobileLogin />} />
        <Route path="/mobile/support" element={<CustomerSupport />} />
        <Route path="/nearby" element={<NearbyDriversMap />} />
        <Route path="/driver-location-simulator" element={<DriverLocationSimulator />} />
        <Route path="/webhook-test" element={<WebhookTester />} />
<Route path="/live-upi-payment" element={<LiveUPIPayment />} />
      <Route path="/payment-test" element={<PaymentTester />} />
        <Route
          path="/*"
          element={
            <PrivateRoute>
              <Layout>
                <Routes>
                  <Route path="/" element={<Dashboard />} />
                  <Route path="/drivers" element={<Drivers />} />
                  <Route path="/orders" element={<Orders />} />
                  <Route path="/customers" element={<Customers />} />
                  <Route path="/vehicles" element={<Vehicles />} />
                  <Route path="/reports" element={<Reports />} />
                  <Route path="/users" element={<UserStatus />} />
                  <Route path="/rides" element={<Rides />} />
                  <Route path="/support" element={<Support />} />
                  <Route path="/driver-status" element={<DriverStatus />} />
                  <Route path="/driver-verification" element={<DriverVerification />} />
                  <Route path="/socket-test" element={<SocketTest />} />
                </Routes>
              </Layout>
            </PrivateRoute>
          }
        />
      </Routes>
    </>
  );
}

export default App;