import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  Grid,
  Chip,
  List,
  ListItem,
  ListItemText,
  Divider,
  Alert,
  IconButton,
  Tooltip,
  Paper,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import {
  PlayArrow as StartIcon,
  Stop as StopIcon,
  Refresh as RefreshIcon,
  Clear as ClearIcon,
  Send as SendIcon,
  ConnectedTv as ConnectedIcon,
  TvOff as DisconnectedIcon,
  CheckCircle as SuccessIcon,
  Error as ErrorIcon,
} from '@mui/icons-material';

const SocketTest = () => {
  const [socketUrl, setSocketUrl] = useState(process.env.REACT_APP_API_URL || 'https://godelivo.com');
  const [sockets, setSockets] = useState({});
  const [logs, setLogs] = useState([]);
  const [connected, setConnected] = useState({ admin: false, drivers: false, bookings: false });
  const [selectedNamespace, setSelectedNamespace] = useState('admin');
  const [eventData, setEventData] = useState('{}');
  const [eventName, setEventName] = useState('');
  const [isTesting, setIsTesting] = useState(false);

  const addLog = (message, type = 'info', namespace = '') => {
    const newLog = {
      id: Date.now(),
      timestamp: new Date().toLocaleTimeString(),
      message,
      type,
      namespace,
    };
    setLogs(prev => [newLog, ...prev].slice(0, 100));
  };

  const connectNamespace = (namespace) => {
    if (sockets[namespace]) {
      addLog(`${namespace} namespace already connected`, 'warning', namespace);
      return;
    }

    const socket = io(`${socketUrl}/${namespace}`);
    
    socket.on('connect', () => {
      addLog(`Connected to /${namespace} namespace`, 'success', namespace);
      setConnected(prev => ({ ...prev, [namespace]: true }));
    });

    socket.on('disconnect', () => {
      addLog(`Disconnected from /${namespace} namespace`, 'error', namespace);
      setConnected(prev => ({ ...prev, [namespace]: false }));
    });

    socket.on('connect_error', (error) => {
      addLog(`Connection error: ${error.message}`, 'error', namespace);
    });

    // Admin namespace events
    if (namespace === 'admin') {
      socket.on('dashboard:stats-update', (data) => {
        addLog(`Received: dashboard:stats-update`, 'info', namespace);
        console.log('Stats:', data);
      });

      socket.on('booking:new', (data) => {
        addLog(`Received: booking:new - Order ${data.bookingId}`, 'info', namespace);
      });

      socket.on('booking:assigned', (data) => {
        addLog(`Received: booking:assigned - Driver ${data.driverId}`, 'info', namespace);
      });

      socket.on('booking:status-updated', (data) => {
        addLog(`Received: booking:status-updated - ${data.status}`, 'info', namespace);
      });

      socket.on('booking:completed', (data) => {
        addLog(`Received: booking:completed`, 'success', namespace);
      });

      socket.on('booking:cancelled', (data) => {
        addLog(`Received: booking:cancelled`, 'warning', namespace);
      });

      socket.on('driver:online', (data) => {
        addLog(`Received: driver:online - ${data.driverId}`, 'success', namespace);
      });

      socket.on('driver:offline', (data) => {
        addLog(`Received: driver:offline - ${data.driverId}`, 'error', namespace);
      });

      socket.on('driver:location-update', (data) => {
        addLog(`Received: driver:location-update`, 'info', namespace);
      });

      socket.on('driver:availability-update', (data) => {
        addLog(`Received: driver:availability-update - Available: ${data.isAvailable}`, 'info', namespace);
      });
    }

    // Drivers namespace events
    if (namespace === 'drivers') {
      socket.on('driver:online', (data) => {
        addLog(`Received: driver:online`, 'success', namespace);
      });

      socket.on('driver:offline', (data) => {
        addLog(`Received: driver:offline`, 'error', namespace);
      });

      socket.on('driver:location-update', (data) => {
        addLog(`Received: driver:location-update`, 'info', namespace);
      });

      socket.on('driver:availability-update', (data) => {
        addLog(`Received: driver:availability-update`, 'info', namespace);
      });

      socket.on('booking:assigned-to-me', (data) => {
        addLog(`Received: booking:assigned-to-me - Order ${data.orderId}`, 'success', namespace);
      });
    }

    // Bookings namespace events
    if (namespace === 'bookings') {
      socket.on('booking:assigned', (data) => {
        addLog(`Received: booking:assigned`, 'info', namespace);
      });

      socket.on('booking:status-updated', (data) => {
        addLog(`Received: booking:status-updated - ${data.status}`, 'info', namespace);
      });

      socket.on('booking:completed', (data) => {
        addLog(`Received: booking:completed`, 'success', namespace);
      });

      socket.on('booking:cancelled', (data) => {
        addLog(`Received: booking:cancelled`, 'warning', namespace);
      });
    }

    setSockets(prev => ({ ...prev, [namespace]: socket }));
  };

  const disconnectNamespace = (namespace) => {
    if (sockets[namespace]) {
      sockets[namespace].disconnect();
      setSockets(prev => {
        const newSockets = { ...prev };
        delete newSockets[namespace];
        return newSockets;
      });
      addLog(`Manually disconnected from /${namespace}`, 'warning', namespace);
    }
  };

  const disconnectAll = () => {
    Object.keys(sockets).forEach(namespace => {
      disconnectNamespace(namespace);
    });
    addLog('All namespaces disconnected', 'warning');
  };

  const emitEvent = () => {
    if (!sockets[selectedNamespace]) {
      addLog(`Not connected to ${selectedNamespace} namespace`, 'error');
      return;
    }

    try {
      const data = JSON.parse(eventData);
      sockets[selectedNamespace].emit(eventName, data);
      addLog(`Emitted: ${eventName}`, 'success', selectedNamespace);
    } catch (error) {
      addLog(`Invalid JSON: ${error.message}`, 'error');
    }
  };

  const clearLogs = () => {
    setLogs([]);
  };

  const runAutomatedTest = async () => {
    setIsTesting(true);
    addLog('Starting automated test suite...', 'info');

    // Connect all namespaces
    connectNamespace('admin');
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    connectNamespace('drivers');
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    connectNamespace('bookings');
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Simulate driver joining
    if (sockets.drivers) {
      sockets.drivers.emit('driver:join', 'test-driver-001');
      addLog('Simulated: driver:join', 'info', 'drivers');
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Simulate location update
      sockets.drivers.emit('driver:location-update', {
        driverId: 'test-driver-001',
        latitude: 28.6139,
        longitude: 77.2090,
      });
      addLog('Simulated: driver:location-update', 'info', 'drivers');
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Simulate availability update
      sockets.drivers.emit('driver:availability-update', {
        driverId: 'test-driver-001',
        isAvailable: false,
      });
      addLog('Simulated: driver:availability-update', 'info', 'drivers');
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    // Simulate booking status update
    if (sockets.bookings) {
      sockets.bookings.emit('booking:join', 'test-booking-001');
      addLog('Simulated: booking:join', 'info', 'bookings');
      await new Promise(resolve => setTimeout(resolve, 1000));

      sockets.bookings.emit('booking:status-update', {
        orderId: 'test-order-001',
        status: 'picked_up',
        previousStatus: 'accepted',
      });
      addLog('Simulated: booking:status-update', 'info', 'bookings');
      await new Promise(resolve => setTimeout(resolve, 1000));

      sockets.bookings.emit('booking:status-update', {
        orderId: 'test-order-001',
        status: 'completed',
        previousStatus: 'picked_up',
      });
      addLog('Simulated: booking:status-update (completed)', 'success', 'bookings');
    }

    addLog('Automated test suite completed', 'success');
    setIsTesting(false);
  };

  useEffect(() => {
    return () => {
      disconnectAll();
    };
  }, []);

  const getLogColor = (type) => {
    switch (type) {
      case 'success': return 'success';
      case 'error': return 'error';
      case 'warning': return 'warning';
      default: return 'info';
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
        Socket.IO Test Interface
      </Typography>
      <Typography variant="body1" sx={{ color: 'text.secondary', mb: 4 }}>
        Test real-time connections and events across all namespaces
      </Typography>

      <Grid container spacing={3}>
        {/* Connection Controls */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent sx={{ p: 3 }}>
              <Typography variant="h6" sx={{ fontWeight: 700, mb: 3 }}>
                Connection Controls
              </Typography>

              <TextField
                fullWidth
                label="Socket URL"
                value={socketUrl}
                onChange={(e) => setSocketUrl(e.target.value)}
                sx={{ mb: 3 }}
                placeholder="https://godelivo.com"
              />

              <Grid container spacing={2} sx={{ mb: 3 }}>
                {['admin', 'drivers', 'bookings'].map((namespace) => (
                  <Grid item xs={4} key={namespace}>
                    <Button
                      fullWidth
                      variant={connected[namespace] ? "contained" : "outlined"}
                      color={connected[namespace] ? "success" : "primary"}
                      onClick={() => connectNamespace(namespace)}
                      disabled={connected[namespace]}
                      startIcon={connected[namespace] ? <SuccessIcon /> : <StartIcon />}
                      sx={{ 
                        py: 1.5,
                        borderRadius: 3,
                        fontWeight: 600,
                      }}
                    >
                      {namespace}
                    </Button>
                  </Grid>
                ))}
              </Grid>

              <Box sx={{ display: 'flex', gap: 2 }}>
                <Button
                  variant="outlined"
                  color="error"
                  onClick={disconnectAll}
                  startIcon={<StopIcon />}
                  sx={{ flex: 1, borderRadius: 3, fontWeight: 600 }}
                >
                  Disconnect All
                </Button>
                <Button
                  variant="contained"
                  onClick={runAutomatedTest}
                  disabled={isTesting}
                  startIcon={<RefreshIcon />}
                  sx={{ 
                    flex: 1, 
                    borderRadius: 3, 
                    fontWeight: 600,
                    background: 'linear-gradient(135deg, #FFB300 0%, #FF8F00 100%)',
                  }}
                >
                  {isTesting ? 'Testing...' : 'Run Test Suite'}
                </Button>
              </Box>
            </CardContent>
          </Card>

          {/* Event Emitter */}
          <Card sx={{ mt: 3 }}>
            <CardContent sx={{ p: 3 }}>
              <Typography variant="h6" sx={{ fontWeight: 700, mb: 3 }}>
                Emit Custom Event
              </Typography>

              <FormControl fullWidth sx={{ mb: 2 }}>
                <InputLabel>Namespace</InputLabel>
                <Select
                  value={selectedNamespace}
                  onChange={(e) => setSelectedNamespace(e.target.value)}
                  label="Namespace"
                >
                  <MenuItem value="admin">/admin</MenuItem>
                  <MenuItem value="drivers">/drivers</MenuItem>
                  <MenuItem value="bookings">/bookings</MenuItem>
                </Select>
              </FormControl>

              <TextField
                fullWidth
                label="Event Name"
                value={eventName}
                onChange={(e) => setEventName(e.target.value)}
                sx={{ mb: 2 }}
                placeholder="driver:location-update"
              />

              <TextField
                fullWidth
                label="Event Data (JSON)"
                value={eventData}
                onChange={(e) => setEventData(e.target.value)}
                multiline
                rows={4}
                sx={{ mb: 2 }}
                placeholder='{"driverId": "123", "latitude": 28.6139}'
              />

              <Button
                fullWidth
                variant="contained"
                onClick={emitEvent}
                startIcon={<SendIcon />}
                sx={{ 
                  borderRadius: 3, 
                  fontWeight: 600,
                  background: 'linear-gradient(135deg, #FFB300 0%, #FF8F00 100%)',
                }}
              >
                Emit Event
              </Button>
            </CardContent>
          </Card>
        </Grid>

        {/* Event Logs */}
        <Grid item xs={12} md={6}>
          <Card sx={{ height: '100%' }}>
            <CardContent sx={{ p: 3, height: '100%' }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                <Typography variant="h6" sx={{ fontWeight: 700 }}>
                  Event Logs
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Chip 
                    label={`${logs.length} events`} 
                    size="small"
                    sx={{ bgcolor: 'rgba(255, 179, 0, 0.1)', color: '#FF8F00', fontWeight: 600 }}
                  />
                  <Tooltip title="Clear Logs">
                    <IconButton onClick={clearLogs} size="small">
                      <ClearIcon />
                    </IconButton>
                  </Tooltip>
                </Box>
              </Box>

              <Paper 
                variant="outlined" 
                sx={{ 
                  height: 500, 
                  overflow: 'auto', 
                  bgcolor: '#1e1e1e',
                  borderRadius: 3,
                }}
              >
                <List dense>
                  {logs.map((log, index) => (
                    <React.Fragment key={log.id}>
                      <ListItem sx={{ py: 1 }}>
                        <ListItemText
                          primary={
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                              <Typography 
                                variant="caption" 
                                sx={{ 
                                  color: '#666',
                                  fontFamily: 'monospace',
                                  minWidth: 70,
                                }}
                              >
                                {log.timestamp}
                              </Typography>
                              {log.namespace && (
                                <Chip 
                                  label={log.namespace}
                                  size="small"
                                  sx={{ 
                                    height: 20, 
                                    fontSize: '0.65rem',
                                    bgcolor: 'rgba(255, 179, 0, 0.2)',
                                    color: '#FFB300',
                                  }}
                                />
                              )}
                              <Typography
                                variant="body2"
                                sx={{
                                  color: 
                                    log.type === 'success' ? '#4caf50' :
                                    log.type === 'error' ? '#f44336' :
                                    log.type === 'warning' ? '#ff9800' : '#fff',
                                  fontFamily: 'monospace',
                                  fontWeight: log.type === 'success' ? 600 : 400,
                                }}
                              >
                                {log.message}
                              </Typography>
                            </Box>
                          }
                        />
                      </ListItem>
                      {index < logs.length - 1 && (
                        <Divider sx={{ borderColor: 'rgba(255,255,255,0.05)' }} />
                      )}
                    </React.Fragment>
                  ))}
                  {logs.length === 0 && (
                    <ListItem>
                      <ListItemText
                        primary={
                          <Typography 
                            variant="body2" 
                            sx={{ color: '#666', textAlign: 'center', py: 4 }}
                          >
                            No events logged yet. Connect to a namespace to start testing.
                          </Typography>
                        }
                      />
                    </ListItem>
                  )}
                </List>
              </Paper>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Test Instructions */}
      <Card sx={{ mt: 3 }}>
        <CardContent sx={{ p: 3 }}>
          <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
            Quick Test Guide
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={4}>
              <Alert severity="info" sx={{ mb: 2 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                  1. Connect Namespaces
                </Typography>
              </Alert>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Click on each namespace button (admin, drivers, bookings) to establish connections. 
                Watch the status change to connected.
              </Typography>
            </Grid>
            <Grid item xs={12} md={4}>
              <Alert severity="success" sx={{ mb: 2 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                  2. Run Automated Tests
                </Typography>
              </Alert>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Click "Run Test Suite" to automatically simulate various events like driver joining, 
                location updates, and booking status changes.
              </Typography>
            </Grid>
            <Grid item xs={12} md={4}>
              <Alert severity="warning" sx={{ mb: 2 }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                  3. Custom Events
                </Typography>
              </Alert>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Use the Emit Custom Event section to send your own events with custom data. 
                Enter event name and JSON data, then click Emit.
              </Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default SocketTest;
