const menuItems = [
  { text: 'Dashboard', icon: icons.dashboard, path: '/' },
  { text: 'Driver Signup', icon: icons.driverSignup, path: '/driver-signup' },
  { text: 'Drivers', icon: icons.truck, path: '/drivers' },
  { text: 'Driver Verification', icon: icons.verification, path: '/driver-verification' },
  { text: 'Orders', icon: icons.cart, path: '/orders' },
  { text: 'Customers', icon: icons.user, path: '/customers' },
  { text: 'Vehicles', icon: icons.car, path: '/vehicles' },
  { text: 'Rides', icon: icons.rides, path: '/rides' },
  { text: 'User Status', icon: icons.userStatus, path: '/users' },
  { text: 'Driver Status', icon: icons.driverStatus, path: '/driver-status' },
  { text: 'Support', icon: icons.support, path: '/support' },
  { text: 'Reports', icon: icons.chart, path: '/reports' },
  { text: 'Socket Test', icon: icons.settings, path: '/socket-test' },
];

const Layout = ({ children }) => {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const navigate = useNavigate();
  const location = useLocation();
  const { notifications } = useApp();
  const { user, logout } = useAuth();

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleProfileMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleProfileMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleProfileMenuClose();
    logout();
  };

  const drawer = (
    <Box>
      <Box
        sx={{
          p: 3,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          borderBottom: '1px solid rgba(0, 0, 0, 0.08)',
        }}
      >
        <Box
          sx={{
            width: 50,
            height: 50,
            borderRadius: 3,
            background: 'linear-gradient(135deg, #FFC107 0%, #FF9800 100%)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            mr: 2,
            boxShadow: '0 4px 15px rgba(255, 193, 7, 0.4)'
          }}
        >
          <RemixIcon path={icons.truck} size={28} />
        </Box>
        <Box>
          <Typography variant="h6" sx={{ fontWeight: 700, color: '#212121' }}>
            GoDelivo
          </Typography>
          <Typography variant="caption" sx={{ color: 'text.secondary' }}>
            Admin Panel
          </Typography>
        </Box>
      </Box>

      <Box sx={{ p: 2 }}>
        <List>
          {menuItems.map((item) => (
            <ListItem key={item.text} disablePadding>
              <ListItemButton
                selected={location.pathname === item.path}
                onClick={() => {
                  navigate(item.path);
                  setMobileOpen(false);
                }}
                sx={{
                  py: 1.5,
                  borderRadius: 2,
                  mb: 0.5,
                  '&.Mui-selected': {
                    backgroundColor: 'rgba(255, 193, 7, 0.15)',
                    '&:hover': {
                      backgroundColor: 'rgba(255, 193, 7, 0.25)',
                    },
                  },
                  '&:hover': {
                    backgroundColor: 'rgba(255, 193, 7, 0.08)',
                  },
                }}
              >
                <ListItemIcon
                  sx={{
                    color: location.pathname === item.path ? '#FF9800' : '#666',
                    minWidth: 40,
                  }}
                >
                  <RemixIcon path={item.icon} />
                </ListItemIcon>
                <ListItemText
                  primary={item.text}
                  primaryTypographyProps={{
                    fontWeight: location.pathname === item.path ? 600 : 500,
                    color: location.pathname === item.path ? '#FF9800' : 'inherit',
                  }}
                />
              </ListItemButton>
            </ListItem>
          ))}
        </List>
      </Box>

      <Divider sx={{ mx: 2 }} />

      <Box sx={{ p: 2 }}>
        <List>
          <ListItem disablePadding>
            <ListItemButton
              sx={{
                borderRadius: 2,
                '&:hover': {
                  backgroundColor: 'rgba(255, 193, 7, 0.08)',
                },
              }}
            >
              <ListItemIcon sx={{ minWidth: 40, color: '#666' }}>
                <RemixIcon path={icons.settings} />
              </ListItemIcon>
              <ListItemText primary="Settings" />
            </ListItemButton>
          </ListItem>
        </List>
      </Box>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}>
      <AppBar
        position="fixed"
        sx={{
          width: { md: `calc(100% - ${drawerWidth}px)` },
          ml: { md: `${drawerWidth}px` },
          background: 'rgba(255, 255, 255, 0.9)',
          backdropFilter: 'blur(10px)',
          boxShadow: '0 2px 12px rgba(0, 0, 0, 0.08)',
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { md: 'none' }, color: '#333' }}
          >
            <RemixIcon path={icons.menu} />
          </IconButton>

          <Box sx={{ flexGrow: 1 }} />

          <Tooltip title="Notifications">
            <IconButton color="inherit" sx={{ mr: 2, color: '#333' }}>
              <Badge badgeContent={notifications.length} color="error">
                <RemixIcon path={icons.notification} />
              </Badge>
            </IconButton>
          </Tooltip>

          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Typography variant="body2" sx={{ mr: 2, display: { xs: 'none', sm: 'block' }, color: '#333' }}>
              {user?.name || 'Admin User'}
            </Typography>
            <IconButton onClick={handleProfileMenuOpen}>
              <Avatar 
                sx={{ 
                  bgcolor: 'primary.main', 
                  color: 'primary.contrastText',
                  background: 'linear-gradient(135deg, #FFC107 0%, #FF9800 100%)'
                }}
              >
                {(user?.name || 'A').charAt(0)}
              </Avatar>
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      <Box
        component="nav"
        sx={{ width: { md: drawerWidth }, flexShrink: { md: 0 } }}
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{ keepMounted: true }}
          sx={{
            display: { xs: 'block', md: 'none' },
            '& .MuiDrawer-paper': { 
              boxSizing: 'border-box', 
              width: drawerWidth,
              background: 'rgba(255, 255, 255, 0.95)',
              backdropFilter: 'blur(10px)'
            },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', md: 'block' },
            '& .MuiDrawer-paper': { 
              boxSizing: 'border-box', 
              width: drawerWidth,
              background: 'rgba(255, 255, 255, 0.95)',
              backdropFilter: 'blur(10px)',
              borderRight: '1px solid rgba(0, 0, 0, 0.05)'
            },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>

      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: { md: `calc(100% - ${drawerWidth}px)` },
          mt: 8,
        }}
      >
        {children}
      </Box>

      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleProfileMenuClose}
        PaperProps={{
          sx: { 
            mt: 1.5, 
            minWidth: 200,
            background: 'rgba(255, 255, 255, 0.95)',
            backdropFilter: 'blur(10px)'
          },
        }}
      >
        <MenuItem onClick={handleProfileMenuClose}>Profile</MenuItem>
        <MenuItem onClick={handleProfileMenuClose}>Settings</MenuItem>
        <Divider />
        <MenuItem onClick={handleLogout} sx={{ color: 'error.main' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <RemixIcon path={icons.logout} size={18} />
            Logout
          </Box>
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default Layout;